package me.arcanebrewery.arcaneBrewery.storage.sqlite;
import me.arcanebrewery.arcaneBrewery.application.discovery.*;
import me.arcanebrewery.arcaneBrewery.storage.jdbc.*;
import me.arcanebrewery.arcaneBrewery.domain.drink.*;
import me.arcanebrewery.arcaneBrewery.domain.discovery.*;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import java.nio.file.*;
import java.time.Instant;
import java.util.*;
import java.util.concurrent.*;
import static org.junit.jupiter.api.Assertions.*;
import static me.arcanebrewery.arcaneBrewery.gameplay.GameplayV2Test.*;
class PermanentRenameTest {
 @TempDir Path dir;
 @Test void anotherBottleAliasAndRestartCannotResetPermanentName(){var file=dir.resolve("one.db");var player=UUID.randomUUID();var p=perfect();var identity=FormulationIdentity.from(p);try(var db=new SqliteStorageProvider(file)){var repo=db.gameplayDiscoveries();repo.recordProduction(player,p,Instant.EPOCH,90,"b1");var m=new DiscoveryMutationRuntime(repo,Runnable::run);m.rename(player,identity,"Permanent").join();repo.recordProduction(player,p,Instant.now(),95,"b2");assertThrows(CompletionException.class,()->m.rename(player,DrinkFingerprint.from(p),"Alias bypass").join());}try(var db=new SqliteStorageProvider(file)){assertEquals("Permanent",db.gameplayDiscoveries().personalName(player,identity).orElseThrow());assertThrows(CompletionException.class,()->new DiscoveryMutationRuntime(db.gameplayDiscoveries(),Runnable::run).rename(player,identity,"Restart bypass").join());}}
 @Test void concurrentRenameHasExactlyOneWinner()throws Exception{try(var db=new SqliteStorageProvider(dir.resolve("race.db"));var pool=Executors.newFixedThreadPool(2)){var player=UUID.randomUUID();db.gameplayDiscoveries().recordProduction(player,perfect(),Instant.EPOCH,90,"b");var barrier=new CountDownLatch(1);var futures=new ArrayList<Future<Boolean>>();for(int i=0;i<2;i++){int n=i;futures.add(pool.submit(()->{barrier.await();try{new DiscoveryMutationRuntime(db.gameplayDiscoveries(),Runnable::run).rename(player,FormulationIdentity.from(perfect()),"Name "+n).join();return true;}catch(CompletionException failed){return false;}}));}barrier.countDown();int winners=0;for(var f:futures)if(f.get(10,TimeUnit.SECONDS))winners++;assertEquals(1,winners);}}
 @Test void storageGuardRejectsDirectMutationAndReset(){var file=dir.resolve("guard.db");try(var db=new SqliteStorageProvider(file)){var player=UUID.randomUUID();var id=FormulationIdentity.from(perfect());db.gameplayDiscoveries().recordProduction(player,perfect(),Instant.EPOCH,90,"b");new DiscoveryMutationRuntime(db.gameplayDiscoveries(),Runnable::run).rename(player,id,"Permanent").join();var factory=new SqliteConnectionFactory(file);assertThrows(RuntimeException.class,()->JdbcTransactions.run(factory,true,c->{try(var q=c.createStatement()){q.executeUpdate("UPDATE personal_recipes SET rename_used=0,personal_name=NULL");}return null;}));assertEquals("Permanent",db.gameplayDiscoveries().personalName(player,id).orElseThrow());}}
 @Test void v4UpgradePreservesExistingNameAndCreatesRecoverableBackup()throws Exception{Class.forName("org.sqlite.JDBC");var file=dir.resolve("old.db");var factory=new SqliteConnectionFactory(file);new me.arcanebrewery.arcaneBrewery.storage.migration.MigrationRunner(factory,SqliteSchema.migrations().subList(0,4)).migrate();JdbcTransactions.run(factory,true,c->{try(var q=c.prepareStatement("INSERT INTO personal_recipes(identity,player_id,recorded_at,temporary_name,personal_name,visibility,provenance) VALUES(?,?,?,?,?,'PRIVATE','INDEPENDENT')")){q.setString(1,"a".repeat(64));q.setString(2,UUID.randomUUID().toString());q.setString(3,Instant.EPOCH.toString());q.setString(4,"Temp");q.setString(5,"Old Name");q.executeUpdate();}return null;});try(var db=new SqliteStorageProvider(file)){assertEquals(SqliteSchema.VERSION,db.schemaVersion());assertEquals(1,JdbcTransactions.<Integer>run(factory,false,c->{try(var q=c.createStatement();var rs=q.executeQuery("SELECT rename_used FROM personal_recipes")){rs.next();return rs.getInt(1);}}));}try(var files=Files.list(dir)){assertEquals(1,files.filter(f->f.toString().endsWith(".bak")).count());}}
}
